-- A cursor declared without SCROLL or NO SCROLL scrolls when its plan can
-- run backward, as pg_cursors shows and backward fetches confirm.
CREATE TABLE s257 (a int, b text);
INSERT INTO s257 VALUES (1, 'x'), (2, 'y'), (3, 'z');
CREATE TABLE u257 (a int);
INSERT INTO u257 VALUES (1), (2);
CREATE VIEW j257 AS SELECT s257.a FROM s257 JOIN u257 USING (a);
BEGIN;
DECLARE c1 CURSOR FOR SELECT * FROM s257;
DECLARE c2 CURSOR FOR SELECT * FROM s257 ORDER BY b;
DECLARE c3 CURSOR FOR VALUES (1), (2);
DECLARE c4 CURSOR FOR VALUES (1);
DECLARE c5 CURSOR FOR SELECT 1;
DECLARE c6 CURSOR FOR SELECT * FROM s257 JOIN u257 USING (a);
DECLARE c7 CURSOR FOR SELECT * FROM s257 JOIN u257 USING (a) ORDER BY a;
DECLARE c16 CURSOR FOR SELECT * FROM s257 JOIN u257 USING (a) ORDER BY b;
DECLARE c8 CURSOR FOR SELECT * FROM j257;
DECLARE c9 CURSOR FOR SELECT count(*) FROM s257;
DECLARE c10 CURSOR FOR SELECT a, count(*) FROM s257 GROUP BY a ORDER BY a;
DECLARE c11 CURSOR FOR SELECT DISTINCT ON (a) a FROM s257 ORDER BY a;
DECLARE c12 CURSOR FOR SELECT * FROM s257 FOR UPDATE;
DECLARE c13 CURSOR FOR SELECT * FROM s257 UNION ALL SELECT * FROM s257;
DECLARE c14 CURSOR FOR SELECT * FROM s257 UNION ALL SELECT 9, 'q';
DECLARE c15 CURSOR FOR SELECT * FROM s257 UNION SELECT 9, 'q';
SELECT name, is_scrollable FROM pg_cursors ORDER BY name COLLATE "C";
COMMIT;
BEGIN;
DECLARE d1 CURSOR FOR SELECT generate_series(1, 3);
DECLARE d2 CURSOR FOR SELECT * FROM generate_series(1, 3);
DECLARE d3 CURSOR FOR SELECT * FROM s257 WHERE a IN (SELECT a FROM u257);
DECLARE d4 CURSOR FOR SELECT * FROM s257 WHERE EXISTS (SELECT 1 FROM u257);
DECLARE d5 CURSOR FOR SELECT * FROM s257 WHERE NOT EXISTS (SELECT 1 FROM u257 WHERE u257.a = s257.a);
DECLARE d6 CURSOR FOR SELECT a, row_number() OVER () FROM s257;
DECLARE d7 CURSOR FOR SELECT a, row_number() OVER () FROM s257 ORDER BY a;
DECLARE d8 CURSOR FOR SELECT * FROM (SELECT a FROM s257 LIMIT 2) q;
DECLARE d9 CURSOR FOR SELECT * FROM s257 TABLESAMPLE SYSTEM (100);
DECLARE d10 CURSOR FOR SELECT * FROM s257 CROSS JOIN (SELECT 1) x;
DECLARE d11 CURSOR FOR WITH w AS (SELECT * FROM s257) SELECT * FROM w;
DECLARE d12 CURSOR FOR SELECT * FROM s257 ORDER BY a LIMIT 2;
SELECT name, is_scrollable FROM pg_cursors ORDER BY name COLLATE "C";
COMMIT;
BEGIN;
DECLARE c1 CURSOR FOR SELECT * FROM s257 ORDER BY a;
FETCH 2 FROM c1;
FETCH PRIOR FROM c1;
DECLARE c9 CURSOR FOR SELECT a FROM s257 GROUP BY a ORDER BY a;
FETCH 2 FROM c9;
FETCH PRIOR FROM c9;
COMMIT;
BEGIN;
DECLARE c6 CURSOR FOR SELECT s257.a FROM s257 JOIN u257 USING (a) WHERE s257.a = 1;
FETCH 1 FROM c6;
FETCH PRIOR FROM c6;
ROLLBACK;
BEGIN;
DECLARE c12 CURSOR FOR SELECT a FROM s257 ORDER BY a FOR UPDATE;
FETCH 1 FROM c12;
FETCH PRIOR FROM c12;
ROLLBACK;
